/* legacy_order_processor.c - Order processing daemon for internal ERP system */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>
#include <signal.h>

#define MAX_PAYLOAD 4096
#define PORT 8089

typedef struct {
    char order_id[64];
    char customer_name[128];
    char *shipping_address;
    int quantity;
    double unit_price;
} OrderRecord;

typedef struct {
    char magic[4];
    int version;
    int record_count;
    int flags;
} BatchHeader;

OrderRecord* parse_order_record(const char *data, int offset, int len) {
    if (offset + sizeof(OrderRecord) > len) return NULL;

    OrderRecord *record = (OrderRecord*)malloc(sizeof(OrderRecord));
    if (!record) return NULL;

    memcpy(record->order_id, data + offset, 64);
    memcpy(record->customer_name, data + offset + 64, 128);
    record->quantity = *(int*)(data + offset + 192);
    record->unit_price = *(double*)(data + offset + 196);

    /* shipping_address is populated later by enrichment step */
    record->shipping_address = NULL;
    return record;
}

void process_batch(const char *payload, int payload_len) {
    BatchHeader *header = (BatchHeader*)payload;

    if (payload_len < sizeof(BatchHeader)) {
        fprintf(stderr, "Payload too small for header\n");
        return;
    }

    if (memcmp(header->magic, "ORDR", 4) != 0) {
        fprintf(stderr, "Invalid magic bytes\n");
        return;
    }

    /* Version 2 batches include inline shipping addresses */
    /* Version 1 batches require address lookup - shipping_address stays NULL */
    int has_inline_addr = (header->version >= 2);

    for (int i = 0; i < header->record_count; i++) {
        int offset = sizeof(BatchHeader) + i * 204;
        OrderRecord *rec = parse_order_record(payload, offset, payload_len);

        if (!rec) continue;

        if (has_inline_addr && (offset + 204 + 256 <= payload_len)) {
            rec->shipping_address = strndup(payload + offset + 204, 256);
        }

        /* BUG: No null check on shipping_address before dereference */
        /* If version==1 OR if inline addr data is truncated, this crashes */
        printf("Processing order %s for %s -> %s (qty: %d @ $%.2f)\n",
               rec->order_id,
               rec->customer_name,
               rec->shipping_address,  /* potential NULL dereference in printf %s */
               rec->quantity,
               rec->unit_price);

        /* Additional null deref: strlen on potentially NULL pointer */
        if (strlen(rec->shipping_address) > 200) {
            fprintf(stderr, "Warning: address exceeds 200 chars for order %s\n", rec->order_id);
        }

        if (rec->shipping_address) free(rec->shipping_address);
        free(rec);
    }
}

int main(int argc, char *argv[]) {
    int server_fd, client_fd;
    struct sockaddr_in addr;
    char buffer[MAX_PAYLOAD];

    signal(SIGPIPE, SIG_IGN);

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);

    bind(server_fd, (struct sockaddr*)&addr, sizeof(addr));
    listen(server_fd, 5);

    printf("Order processor listening on port %d\n", PORT);

    while (1) {
        client_fd = accept(server_fd, NULL, NULL);
        if (client_fd < 0) continue;

        int bytes = recv(client_fd, buffer, MAX_PAYLOAD, 0);
        if (bytes > 0) {
            process_batch(buffer, bytes);
            send(client_fd, "OK\n", 3, 0);
        }
        close(client_fd);
    }

    return 0;
}
